<?php
namespace qqworld_collector\module; use qqworld_collector\lib; class additional extends lib { var $options; var $module = 'additional'; var $thumbnails = null; public function __construct() { add_filter( 'has_post_thumbnail', array($this, 'has_post_thumbnail'), 10, 3 ); add_filter( 'post_thumbnail_html', array($this, 'post_thumbnail_html'), 10, 5 ); } public function has_post_thumbnail($has_thumbnail, $post, $thumbnail_id) { if ($this->options->qc_auxiliary_settings_auto_featured_image && !$has_thumbnail && !is_admin()) { $post = is_object($post) ? $post : get_post($post); $preg = preg_match_all('/<img[\s\S]*? src="([\s\S]*?)"[\s\S]*?>/i', $post->post_content, $matches); if ($preg) { $this->thumbnails = $matches[1]; return true; } } return $has_thumbnail; } public function post_thumbnail_html($html, $post_id, $post_thumbnail_id, $size, $attr) { if ($html || is_admin() || !$this->options->qc_auxiliary_settings_auto_featured_image || !apply_filters( 'qqworld-collector-activated-module-' . $this->module, false ) ) return $html; $html = apply_filters( 'qqworld-collector-additional-post-thumbnail-html', $html, $post_id, $post_thumbnail_id, $size, $attr, $this ); $this->thumbnails = null; return $html; } } ?>